#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;

    Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int idx, long long val) {
        while (idx <= n) {
            bit[idx] += val;
            idx += idx & -idx;
        }
    }

    long long sum(int idx) {
        long long res = 0;
        while (idx > 0) {
            res += bit[idx];
            idx -= idx & -idx;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    Fenwick fw(N);
    vector<long long> people(N + 1);

    for (int i = 1; i <= N; i++) {
        cin >> people[i];
        fw.add(i, people[i]);
    }

    while (Q--) {
        int type;
        cin >> type;

        if (type == 0) {
            int K;
            long long P;
            cin >> K >> P;
            long long delta = P - people[K];
            people[K] = P;
            fw.add(K, delta);
        } else {
            int K;
            cin >> K;
            cout << fw.sum(K) << '\n';
        }
    }

    return 0;
}
